// Generated by Wrangler - simplified to just Env types
// Runtime types come from @cloudflare/workers-types

// Text file imports (for Wrangler rules)
declare module '*.html' {
    const content:string
    export default content
}

declare module '*.css' {
    const content:string
    export default content
}

declare namespace Cloudflare {
    interface Env {
        // Core config
        NODE_ENV:string;

        // Cloudflare bindings
        DB:D1Database;
        MY_DO:DurableObjectNamespace<import('./src/server/index').MyDurableObject>;
        EXAMPLE_CACHE:KVNamespace;
        ASSETS:Fetcher;  // Static assets binding

        // Session management (cookies)
        SESSION_SECRET:string;
        // Webhooks
        WEBHOOK_SECRET:string;
    }
}

interface Env extends Cloudflare.Env {}
